import { readJSON, writeJSON } from '../../js/storage.js';
import { treeProgress } from '../../core/components/tree-progress.js';
import { analyzeEvent } from '../../core/engine/event-analyzer.js';

const STORAGE_KEY='lega.eventos';
const CONFIG_KEY='lega.orcamentos.config';
const PRICE_KEY='lega.precos.vigencias';
const CLIENTS_KEY='lega.clientes';
const STATUS=[['orcamento','Orçamento','🌰'],['aceito','Interesse confirmado','🌱'],['contrato','Contrato assinado','🌿'],['entrada','Entrada paga','🌳'],['preparacao','Preparação','🌳'],['pronto','Evento pronto','🌳'],['realizado','Memória','🌸']];
const TIPOS=['Aniversário infantil','Aniversário adulto','Corporativo','Casamento','Formatura','Apresentação','Chá de bebê','Evento especial'];
const PACOTES=['Lega Kids','Lega Básico','Lega Tour','Lega Transcender'];
const POLITICAS=['Inclusa','Por adesão','Cobrança ao cliente pelo consumo','Não haverá'];
const CONFIG_PADRAO={entradaPercentual:30,descontoAvista:5,pacotes:{
'Lega Kids':{duracao:3,permiteHoraExtra:false,valorHoraExtra:0,valorPorConvidado:50,faixas:[[25,1000],[35,1000],[45,1000],[55,1000],[65,1270],[75,1270],[85,1270],[95,1270],[105,1540],[115,1540]],gastronomia:['Salgados variados','Doces tradicionais','Bolo','Refrigerante, suco e água'],estrutura:['Brinquedos da Lega','Equipe de apoio','Espaço exclusivo por 3 horas']},
'Lega Básico':{duracao:3,permiteHoraExtra:true,valorHoraExtra:450,valorPorConvidado:42,faixas:[[25,1750],[35,1750],[45,1750],[50,1750],[60,2020],[70,2020],[80,2020],[90,2020],[100,2290],[110,2290]],gastronomia:['Cardápio do pacote Básico','Refrigerante, suco e água'],estrutura:['Estrutura completa da Lega','Equipe de apoio','Espaço exclusivo por 3 horas']},
'Lega Tour':{duracao:4,permiteHoraExtra:true,valorHoraExtra:700,valorPorConvidado:70,faixas:[[25,1500],[35,1600],[45,1650],[50,1650],[60,1700],[70,1700],[80,1750],[90,1750],[100,1800],[110,1800]],gastronomia:['Cardápio completo do pacote Tour','Doces e bolo','Refrigerante, suco e água'],estrutura:['Estrutura completa da Lega','Equipe de apoio','Espaço exclusivo por 4 horas']},
'Lega Transcender':{duracao:4,permiteHoraExtra:true,valorHoraExtra:750,valorPorConvidado:75,faixas:[[25,1600],[35,1700],[45,1850],[50,1850],[60,1900],[70,1900],[80,1950],[90,1950],[100,2100],[110,2100]],gastronomia:['Entrada com linguicinha parrillera e polenta frita','Rodízio com 14 variedades de salgados','Batata frita','Água com gás e sem gás, refrigerante e suco','Doces gourmet e bolo'],estrutura:['Espaço completo e climatizado','Equipe de apoio durante o evento','Ambiente preparado para receber crianças e família','Atendimento organizado para uma experiência tranquila']}
}};
const CHECKLIST_PADRAO=[['contratacao','Contratação',['Recreadores','Garçons','Pessoal da cozinha','Extras do pacote']],['alimentacao','Alimentação',['Salgados','Linguiça','Polenta','Batata frita','Doces','Bolo','Maionese','Óleo']],['organizacao','Organização',['Decoração','Vela','Lista de convidados','Papelaria','Garfinhos','Guardanapos','Balões','Encomenda de bolo e doces']],['financeiro','Financeiro',['Entrada recebida','Saldo conferido']]];
let state={view:'list',selectedId:null,query:'',status:'todos',activeTab:'menu',editingEventId:null};
const uid=(p='id')=>`${p}_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
const nowISO=()=>new Date().toISOString();
const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const dateBR=v=>{if(!v)return'Data a definir';const[y,m,d]=v.split('-').map(Number);return new Intl.DateTimeFormat('pt-BR').format(new Date(y,m-1,d));};
const getConfig=()=>readJSON(CONFIG_KEY,CONFIG_PADRAO);
const currentYear=()=>new Date().getFullYear();
function defaultPriceTables(){const y=currentYear();return[{id:`vig_${y}`,ano:y,reajuste:0,pacotes:JSON.parse(JSON.stringify(CONFIG_PADRAO.pacotes)),createdAt:nowISO()}];}
function getPriceTables(){const t=readJSON(PRICE_KEY,null);if(Array.isArray(t)&&t.length)return t;const d=defaultPriceTables();writeJSON(PRICE_KEY,d);return d;}
function tableForDate(data,forcedYear=null){const year=Number(forcedYear||(data?String(data).slice(0,4):currentYear()));const tables=getPriceTables().sort((a,b)=>a.ano-b.ano);return tables.find(t=>Number(t.ano)===year)||tables.filter(t=>Number(t.ano)<=year).at(-1)||tables.at(-1);}
function createPriceTableForYear(ano,reajuste=10,arredondamento=10){let ts=getPriceTables();ano=Number(ano);if(!ano||ts.some(t=>Number(t.ano)===ano))return ts.find(t=>Number(t.ano)===ano)||null;const source=[...ts].sort((a,b)=>a.ano-b.ano).filter(t=>Number(t.ano)<ano).at(-1)||ts.at(-1);if(!source)return null;const rate=1+Number(reajuste||0)/100;const round=Number(arredondamento||0);const cp=JSON.parse(JSON.stringify(source.pacotes||{}));Object.values(cp).forEach(pkg=>{const adj=v=>{const n=Number(v||0)*rate;return round?Math.round(n/round)*round:Number(n.toFixed(2))};pkg.valorPorConvidado=adj(pkg.valorPorConvidado);pkg.valorHoraExtra=adj(pkg.valorHoraExtra);pkg.faixas=(pkg.faixas||[]).map(([lim,val])=>[lim,adj(val)])});const table={id:`vig_${ano}`,ano,reajuste:Number(reajuste||0),origemAno:Number(source.ano),pacotes:cp,createdAt:nowISO()};ts=[...ts,table].sort((a,b)=>a.ano-b.ano);writeJSON(PRICE_KEY,ts);return table;}
function clients(){return readJSON(CLIENTS_KEY,[]);}
function saveClients(v){writeJSON(CLIENTS_KEY,v);}
const saveEvents=v=>writeJSON(STORAGE_KEY,v);
const statusMeta=k=>STATUS.find(x=>x[0]===k)||STATUS[0];
const progressFor=k=>({orcamento:8,aceito:22,contrato:38,entrada:54,preparacao:70,pronto:88,realizado:100})[k]||8;
const history=(label,detail='')=>({id:uid('hist'),label,detail,at:nowISO()});
const checklistInicial=()=>CHECKLIST_PADRAO.flatMap(([categoria,,itens])=>itens.map(titulo=>({id:uid('chk'),categoria,titulo,concluido:false})));
function migrate(e){if(e.orcamentos?.length)return e;const q={id:uid('orc'),versao:1,cliente:e.cliente,nome:e.nome,data:e.data,convidadosTotal:Number(e.convidadosTotal||0),pacote:e.pacote||'Lega Tour',horasExtras:Number(e.horasExtras||0),tipo:e.tipo||'Aniversário infantil',horaInicio:e.horaInicio||'',tema:e.tema||'',observacoes:e.observacoes||'',valor:Number(e.valorContrato||0),createdAt:e.createdAt||nowISO()};return{...e,orcamentos:[q],orcamentoEscolhidoId:q.id};}
function getEvents(){const raw=readJSON(STORAGE_KEY,[]);const migrated=raw.map(migrate);if(JSON.stringify(raw)!==JSON.stringify(migrated))saveEvents(migrated);return migrated;}
function selectedQuote(e){return e.orcamentos?.find(q=>q.id===e.orcamentoEscolhidoId)||e.orcamentos?.at(-1);}
function totalGuests(e){const q=selectedQuote(e);return Number(q?.convidadosTotal||e.convidadosTotal||0)||(Number(e.adultos||0)+Number(e.criancas||0)+Number(e.menores4||0));}
function calcQuote(pacote,convidados,horasExtras=0,data='',vigenciaAno=null){const tabela=tableForDate(data,vigenciaAno);const cfg=tabela?.pacotes?.[pacote]||getConfig().pacotes[pacote]||getConfig().pacotes['Lega Tour'];const qtd=Math.max(0,Number(convidados||0));const faixa=cfg.faixas.find(([lim])=>qtd<=lim)||cfg.faixas.at(-1);const extras=cfg.permiteHoraExtra?Math.max(0,Number(horasExtras||0)):0;const total=qtd*Number(cfg.valorPorConvidado||0)+Number(faixa?.[1]||0)+extras*Number(cfg.valorHoraExtra||0);return{tabela,qtd,faixa:Number(faixa?.[0]||0),valorPorConvidado:Number(cfg.valorPorConvidado||0),aluguel:Number(faixa?.[1]||0),extras,valorHoraExtra:Number(cfg.valorHoraExtra||0),valorExtras:extras*Number(cfg.valorHoraExtra||0),total,duracao:Number(cfg.duracao||4)+extras,cfg};}
function paymentSummary(total){const c=getConfig();const entrada=total*Number(c.entradaPercentual||30)/100;return{entrada,avista:total*(1-Number(c.descontoAvista||5)/100),saldo:total-entrada,desconto:Number(c.descontoAvista||5),entradaPerc:Number(c.entradaPercentual||30)};}
function field(name,label,type='text',value='',options=null,extra=''){if(options)return`<div class="field"><label>${label}</label><select name="${name}" ${extra}>${options.map(o=>`<option value="${esc(o)}" ${String(value)===String(o)?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;return`<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}

function listView(){const all=getEvents();const filtered=[...all].sort((a,b)=>(selectedQuote(a)?.data||'9999').localeCompare(selectedQuote(b)?.data||'9999')).filter(e=>{const q=selectedQuote(e)||{};const text=`${q.nome||''} ${q.cliente||''} ${q.pacote||''}`.toLowerCase();return(!state.query||text.includes(state.query.toLowerCase()))&&(state.status==='todos'||e.status===state.status)});return`<div class="page-grid"><section class="events-header"><div><span class="eyebrow">CICLO DA FESTA</span><h2>Orçamentos e eventos</h2><p>Os orçamentos ficam salvos e o evento segue adiante a partir da versão escolhida.</p></div><button class="btn btn-primary" data-action="new-event">+ Iniciar orçamento</button></section><section class="events-toolbar panel"><div class="search-field"><input id="eventSearch" value="${esc(state.query)}" placeholder="Buscar cliente ou evento"></div><select id="eventStatusFilter"><option value="todos">Todos os status</option>${STATUS.map(([id,l])=>`<option value="${id}" ${state.status===id?'selected':''}>${l}</option>`).join('')}</select><span class="events-count">${filtered.length} de ${all.length}</span></section>${all.length?`<section class="events-list">${filtered.map(eventCard).join('')}</section>`:`<section class="panel events-empty"><img src="assets/botanica/semente.svg" class="events-empty__icon"><h2>Inicie o primeiro orçamento</h2><p>Informe o essencial, gere a proposta e continue somente se o cliente demonstrar interesse.</p><button class="btn btn-primary" data-action="new-event">Iniciar orçamento</button></section>`}</div>`;}
function eventCard(e){const q=selectedQuote(e)||{};const[,label,icon]=statusMeta(e.status);return`<article class="event-card"><button class="event-card__main" data-action="open-event" data-id="${e.id}"><span class="event-card__date"><strong>${q.data?q.data.slice(8,10):'--'}</strong><small>${q.data?new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(new Date(`${q.data}T12:00:00`)).replace('.',''):'a definir'}</small></span><span class="event-card__body"><strong>${esc(q.nome||q.cliente||'Novo orçamento')}</strong><small>${esc(q.cliente)} · ${q.convidadosTotal||0} convidados · ${esc(q.pacote||'')}</small></span><span class="status-pill status-${e.status}">${icon} ${label}</span></button></article>`;}

function quoteForm(e=null){const base=e?selectedQuote(e):null;const v=(k,f='')=>base?.[k]??f;const pacote=v('pacote','Lega Tour');const data=v('data','');const tabela=tableForDate(data,v('vigenciaAno'));const calc=calcQuote(pacote,v('convidadosTotal',0),v('horasExtras',0),data,tabela?.ano);return`<div class="page-grid event-form-page"><section class="events-header"><div><button class="back-link" data-action="${e?'back-workspace':'back-list'}">← Voltar</button><span class="eyebrow">${e?'NOVA VERSÃO':'NOVO ORÇAMENTO'}</span><h2>${e?'Criar nova versão':'Iniciar orçamento'}</h2><p>O valor oficial é escolhido pela data do evento e pode receber uma negociação registrada.</p></div></section><form id="quoteForm" class="event-form"><input type="hidden" name="eventId" value="${esc(e?.id||'')}"><input type="hidden" name="valorFinalCalculado" value="${calc.total}"><section class="panel form-section"><div class="form-section__title"><span>1</span><div><h3>Informações iniciais</h3><p>Preencha os dados conhecidos no primeiro contato.</p></div></div><div class="form-grid">${field('cliente','Nome do interessado','text',v('cliente'),'','required')}${field('nome','Nome do evento','text',v('nome'),'','placeholder="Opcional"')}${field('data','Data pretendida','date',data,'','required')}${field('convidadosTotal','Total de convidados','number',v('convidadosTotal'),'','min="1" required')}${field('pacote','Pacote','text',pacote,PACOTES,'required')}${field('horasExtras','Hora extra','number',v('horasExtras',0),'','min="0" max="4" step="1"')}${field('vigenciaAno','Tabela de preços','text',String(tabela?.ano||currentYear()),getPriceTables().map(t=>String(t.ano)),'required')}</div><div id="missingPriceTable" class="price-table-warning" hidden><div><strong>⚠ Não existe tabela de preços para <span id="missingPriceYear"></span>.</strong><p>Crie agora usando a tabela anterior com reajuste sugerido de 10%. Os valores poderão ser revisados em Configurações.</p></div><button type="button" class="btn btn-primary" data-action="create-price-table">Criar tabela</button></div></section><section class="panel quote-calculation"><div><span class="eyebrow">VALOR OFICIAL DA TABELA <b id="quoteTableYear">${tabela?.ano||''}</b></span><h3 id="quoteBaseTotal">${money(calc.total)}</h3><p id="quoteFormula">${calc.qtd} convidados + faixa do pacote${calc.valorExtras?` + ${calc.extras}h extra`:''}</p></div><div class="quote-duration"><strong id="quoteDuration">${calc.duracao}h</strong><small>duração total</small></div></section><section class="panel form-section"><div class="form-section__title"><span>2</span><div><h3>Negociação comercial</h3><p>O ajuste vale apenas para esta versão e não altera a tabela oficial.</p></div></div><div class="form-grid">${field('ajusteTipo','Tipo de negociação','text',v('ajusteTipo','Sem alteração'),['Sem alteração','Desconto (%)','Acréscimo (%)','Valor final negociado'])}<div id="percentualNegociacao" class="negotiation-option">${field('ajustePercentual','Percentual','number',v('ajustePercentual',0),null,'step="0.01" min="0"')}</div><div id="valorManualNegociacao" class="negotiation-option">${field('valorFinalManual','Valor final negociado','number',v('valorFinalManual',''),null,'step="0.01" min="0"')}</div>${field('motivoNegociacao','Motivo','text',v('motivoNegociacao',''),['','Cliente recorrente','Promoção especial','Indicação','Convênio','Data disponível','Negociação comercial','Outro'])}<div class="field field-full"><label>Observação da negociação</label><textarea name="observacaoNegociacao" rows="3">${esc(v('observacaoNegociacao'))}</textarea></div></div><div class="payment-preview"><div><small>Valor oficial</small><strong id="quoteOfficial">${money(calc.total)}</strong></div><div><small>Valor final do orçamento</small><strong id="quoteTotal">${money(calc.total)}</strong></div></div></section><section class="panel form-section"><div class="form-section__title"><span>3</span><div><h3>Informações opcionais</h3><p>Podem ser completadas depois.</p></div></div><div class="form-grid">${field('tipo','Tipo do evento','text',v('tipo','Aniversário infantil'),TIPOS)}${field('horaInicio','Horário desejado','time',v('horaInicio'))}${field('tema','Tema','text',v('tema'),'','placeholder="Opcional"')}<div class="field field-full"><label>Observações</label><textarea name="observacoes" rows="4">${esc(v('observacoes'))}</textarea></div></div></section><div class="form-actions"><button type="button" class="btn btn-ghost" data-action="${e?'back-workspace':'back-list'}">Cancelar</button><button class="btn btn-primary" type="submit">Gerar e salvar orçamento</button></div></form></div>`;}

function quoteVersions(e){const chosen=e.orcamentoEscolhidoId;return`<section class="panel"><div class="panel-header"><div><h2>Orçamentos salvos</h2><p>Escolha a proposta que servirá de base para continuar o evento.</p></div><button class="btn btn-primary" data-action="new-version">+ Nova versão</button></div><div class="quote-version-list">${[...(e.orcamentos||[])].sort((a,b)=>b.versao-a.versao).map(q=>`<article class="quote-version ${q.id===chosen?'selected':''}"><div><span class="version-badge">V${q.versao}</span><strong>${esc(q.pacote)} · ${money(q.valor)}</strong><small>${dateBR(q.data)} · ${q.convidadosTotal} convidados · gerado em ${new Date(q.createdAt).toLocaleString('pt-BR')}</small></div><div class="quote-version__actions">${q.id===chosen?'<span class="chosen-label">✓ Escolhido</span>':`<button class="btn btn-ghost" data-action="choose-quote" data-quote="${q.id}">Escolher</button>`}<button class="btn btn-ghost" data-action="print-version" data-quote="${q.id}">Abrir PDF</button></div></article>`).join('')}</div></section>`;}
function budgetContent(e){const q=selectedQuote(e);if(!q)return'';const p=paymentSummary(q.valor);return`${quoteVersions(e)}<section class="panel budget-sheet"><div class="panel-header"><div><h2>Orçamento escolhido</h2><p>Esta é a versão usada para dar continuidade ao evento.</p></div><button class="btn btn-primary" data-action="print-budget">Abrir orçamento / PDF</button></div><div class="budget-brand"><img src="assets/logo/logo-lega.png"><div><strong>${esc(q.pacote)}</strong><small>Versão ${q.versao} · ${dateBR(q.data)}</small></div></div><dl class="budget-data"><div><dt>Interessado</dt><dd>${esc(q.cliente)}</dd></div><div><dt>Convidados</dt><dd>${q.convidadosTotal}</dd></div><div><dt>Duração</dt><dd>${calcQuote(q.pacote,q.convidadosTotal,q.horasExtras).duracao} horas</dd></div><div><dt>Valor</dt><dd>${money(q.valor)}</dd></div></dl><div class="payment-preview"><div><small>À vista com ${p.desconto}% de desconto</small><strong>${money(p.avista)}</strong></div><div><small>Parcelado</small><strong>Entrada ${money(p.entrada)}</strong><span>+ saldo em até 6x</span></div></div>${((q.ajusteTipo&&q.ajusteTipo!=='Sem ajuste'&&q.ajusteTipo!=='Sem alteração')||q.observacaoNegociacao)?`<div class="commercial-note"><strong>Registro interno da negociação</strong><p>Valor oficial: ${money(q.valorOficial||q.valor)} · Valor final: ${money(q.valor)}</p>${q.observacaoNegociacao?`<p><b>Observação:</b> ${esc(q.observacaoNegociacao)}</p>`:''}</div>`:''}${e.status==='orcamento'?`<div class="interest-callout"><div><strong>O cliente confirmou interesse nesta versão?</strong><p>O evento seguirá a partir do orçamento escolhido.</p></div><button class="btn btn-primary" data-action="accept-quote">Confirmar interesse</button></div>`:''}</section>`;}
function placeholder(t,p){return`<section class="panel events-empty"><h2>${t}</h2><p>${p}</p></section>`;}
function contractContent(e){
  if(e.status==='orcamento')return placeholder('Contrato ainda não liberado','Primeiro confirme o interesse do cliente no orçamento escolhido.');
  const q=selectedQuote(e)||{};const c=e.clienteContrato||{};const lista=clients();const versions=[...(e.contratos||[])].sort((a,b)=>b.versao-a.versao);
  const versionList=versions.length?`<section class="panel"><div class="panel-header"><div><h2>Contratos salvos</h2><p>Cada geração cria uma nova versão. As anteriores permanecem preservadas.</p></div></div><div class="quote-version-list">${versions.map(v=>`<article class="quote-version"><div><span class="version-badge">V${v.versao}</span><strong>${esc(v.cliente?.nome||q.cliente)} · ${money(v.orcamento?.valor||0)}</strong><small>Gerado em ${new Date(v.createdAt).toLocaleString('pt-BR')}</small></div><div class="quote-version__actions"><button class="btn btn-ghost" data-action="open-contract" data-contract="${v.id}">Abrir versão</button></div></article>`).join('')}</div></section>`:'';
  if(e.contratoAssinado||['contrato','entrada','preparacao','pronto','realizado'].includes(e.status))return`${versionList}<section class="panel process-card process-card--done"><div><span class="process-icon">✓</span><div><h2>Contrato assinado</h2><p>Contrato de ${esc(c.nome||q.cliente||'cliente')} confirmado. O próximo passo é registrar a entrada.</p></div></div><div class="form-actions"><button class="btn btn-ghost" data-action="open-contract" data-contract="${versions[0]?.id||''}">Abrir contrato</button><button class="btn btn-primary" data-action="go-finance">Ir para pagamento da entrada</button></div></section>`;
  const assinaturaPendente=versions.length?`<section class="panel process-card"><div><span class="process-icon">✍️</span><div><h2>Contrato aguardando assinatura</h2><p>Depois que o cliente assinar, confirme aqui para liberar o pagamento da entrada e as próximas etapas do evento.</p></div></div><div class="form-actions"><button class="btn btn-ghost" data-action="open-contract" data-contract="${versions[0]?.id||''}">Abrir contrato</button><button class="btn btn-primary" data-action="sign-contract">Marcar como assinado</button></div></section>`:'';
  return`${versionList}${assinaturaPendente}<form id="contractForm" class="panel event-form"><div class="panel-header"><div><h2>${versions.length?'Gerar nova versão do contrato':'Assistente de contrato'}</h2><p>${versions.length?'Use somente quando precisar corrigir dados ou emitir outra versão.':'Localize um cliente existente ou preencha os dados. Ao gerar, o sistema preserva um retrato completo do acordo.'}</p></div><button class="btn btn-primary" type="submit">${versions.length?'Salvar nova versão':'Salvar e gerar contrato'}</button></div><div class="form-grid"><div class="field field-full"><label>Buscar cliente cadastrado</label><input id="clientSearch" list="clientOptions" placeholder="Digite nome, CPF ou telefone"><datalist id="clientOptions">${lista.map(x=>`<option value="${esc(x.nome)}">${esc(x.cpf||'')} ${esc(x.telefone||'')}</option>`).join('')}</datalist></div>${field('nome','Nome completo','text',c.nome||q.cliente,null,'required')}${field('cpf','CPF','text',c.cpf||'',null,'required')}${field('telefone','WhatsApp/telefone','text',c.telefone||'',null,'required')}${field('email','E-mail','email',c.email||'')}${field('cep','CEP','text',c.cep||'')}${field('endereco','Rua e número','text',c.endereco||'',null,'required')}${field('bairro','Bairro','text',c.bairro||'',null,'required')}${field('cidade','Cidade','text',c.cidade||'Caçapava do Sul',null,'required')}${field('estado','Estado','text',c.estado||'RS',null,'required')}</div><div class="interest-callout"><div><strong>Snapshot automático</strong><p>Cliente, orçamento, tabela, pacote, serviços, valor e condições ficam congelados nesta versão.</p></div><button type="button" class="btn btn-ghost" data-action="preview-contract">Pré-visualizar</button></div></form>`;
}
function financeContent(e){
  if(!e.contratoAssinado&&!['contrato','entrada','preparacao','pronto','realizado'].includes(e.status))return placeholder('Pagamento ainda não liberado','O pagamento da entrada será registrado depois da assinatura do contrato.');
  const q=selectedQuote(e);const p=paymentSummary(q?.valor||0);
  if(e.entradaPaga)return`<section class="panel process-card process-card--done"><div><span class="process-icon">✓</span><div><h2>Entrada confirmada</h2><p>${money(e.entradaValor||p.entrada)} recebidos em ${dateBR(e.entradaData)}${e.entradaForma?` · ${esc(e.entradaForma)}`:''}. O evento está liberado para completar os detalhes e iniciar o checklist.</p></div></div><button class="btn btn-primary" data-action="go-details">Completar dados da festa</button></section>`;
  return`<form id="entryForm" class="panel event-form"><div class="panel-header"><div><h2>Pagamento da entrada</h2><p>Registre a entrada para confirmar a reserva e liberar a organização detalhada da festa.</p></div><button class="btn btn-primary">Confirmar entrada paga</button></div><div class="form-grid">${field('entradaValor','Valor recebido','number',p.entrada,null,'min="0" step="0.01" required')}${field('entradaData','Data do pagamento','date',new Date().toISOString().slice(0,10),null,'required')}${field('entradaForma','Forma de pagamento','text','Pix',['Pix','Dinheiro','Cartão','Transferência','Outro'],'required')}</div></form>`;
}
function detailsUnlocked(e){return e.entradaPaga||['entrada','preparacao','pronto','realizado'].includes(e.status);}

function detailsContent(e){const q=selectedQuote(e);return`<form id="detailsForm" class="panel event-form"><div class="panel-header"><div><h2>Completar evento</h2><p>Contrato assinado e entrada confirmada. Agora os detalhes da festa podem ser preenchidos conforme forem definidos.</p></div><button class="btn btn-primary">Salvar alterações</button></div><div class="form-grid">${field('adultos','Adultos','number',e.adultos||0,null,'min="0"')}${field('criancas','Crianças','number',e.criancas||0,null,'min="0"')}${field('menores4','Menores de 4 anos','number',e.menores4||0,null,'min="0"')}${field('tema','Tema','text',e.tema||q?.tema||'')}${field('horaInicio','Início','time',e.horaInicio||q?.horaInicio||'')}${field('horaFim','Término','time',e.horaFim||'')}${field('alimentacaoPolitica','Alimentação','text',e.alimentacaoPolitica||'Inclusa',POLITICAS)}${field('naoAlcoolicasPolitica','Bebidas não alcoólicas','text',e.naoAlcoolicasPolitica||'Inclusa',POLITICAS)}${field('alcoolicasPolitica','Bebidas alcoólicas','text',e.alcoolicasPolitica||'Por adesão',POLITICAS)}</div></form>`;}
function checklistContent(e){const groups=CHECKLIST_PADRAO.map(([id,label])=>[id,label,(e.checklist||[]).filter(i=>i.categoria===id)]);return`<section class="panel"><div class="panel-header"><div><h2>Checklist do evento</h2><p>${(e.checklist||[]).filter(i=>i.concluido).length} de ${(e.checklist||[]).length} concluídas</p></div></div><div class="checklist-grid">${groups.map(([id,l,itens])=>`<div class="checklist-group"><h3>${l}</h3>${itens.map(i=>`<label class="check-item"><input type="checkbox" data-action="toggle-check" data-id="${i.id}" ${i.concluido?'checked':''}><span>${esc(i.titulo)}</span></label>`).join('')}</div>`).join('')}</div><form id="checkAddForm" class="check-add"><select name="categoria">${CHECKLIST_PADRAO.map(([id,l])=>`<option value="${id}">${l}</option>`).join('')}</select><input name="titulo" required placeholder="Nova tarefa"><button class="btn btn-primary">Adicionar</button></form></section>`;}
function historyContent(e){return`<section class="panel"><h2>Histórico</h2><div class="timeline">${[...(e.historico||[])].reverse().map(h=>`<div class="timeline-item"><span></span><div><strong>${esc(h.label)}</strong><p>${esc(h.detail||'')}</p><small>${new Date(h.at).toLocaleString('pt-BR')}</small></div></div>`).join('')}</div></section>`;}
function eventAnalysis(e){
  const analysis=analyzeEvent(e,selectedQuote(e));
  const pendingPreview=analysis.pending.slice(0,4);
  const health=analysis.health||{status:'attention',label:'Atenção',reason:'Análise operacional indisponível.'};
  const daysText=analysis.daysRemaining===null?'Data não definida':analysis.daysRemaining<0?`${Math.abs(analysis.daysRemaining)} dia(s) após a data`:analysis.daysRemaining===0?'Evento hoje':`Faltam ${analysis.daysRemaining} dia(s)`;
  const healthIcon={ok:'🟢',attention:'🟡',late:'🔴'}[health.status]||'🟡';
  return `<section class="event-analysis panel event-analysis--${health.status}"><div class="event-health"><div class="event-health__status"><span class="event-health__icon">${healthIcon}</span><div><small>SAÚDE DO EVENTO</small><strong>${esc(health.label)}</strong></div></div><div class="event-health__date">${esc(daysText)}</div><p>${esc(health.reason)}</p></div><div class="event-timeline"><div>🧑 Cliente</div><div>➡️ Orçamento</div><div>➡️ Contrato</div><div>➡️ Entrada</div><div>➡️ Preparação</div><div>➡️ Evento</div></div><div class="event-analysis__heading"><div><span class="eyebrow">ANÁLISE DO EVENTO</span><h2>${esc(analysis.phase)}</h2></div><span class="event-analysis__badge">Lega OS</span></div><div class="event-analysis__next"><small>Próxima ação</small><strong>${esc(analysis.nextAction)}</strong></div><div class="event-analysis__pending"><small>Pendências</small>${analysis.pending.length?`<ul>${pendingPreview.map(item=>`<li>${esc(item)}</li>`).join('')}${analysis.pending.length>pendingPreview.length?`<li>+ ${analysis.pending.length-pendingPreview.length} pendência(s)</li>`:''}</ul>`:'<p>Não há pendências nesta etapa.</p>'}</div></section>`;
}
function eventMenu(e){
  const pending=(e.checklist||[]).filter(i=>!i.concluido).length;
  const versions=(e.contratos||[]).length;
  const items=[
    ['orcamento','💰','Orçamento',`${e.orcamentos?.length||0} versão(ões)`,''],
    ['contrato','📝','Contrato',versions?`${versions} versão(ões)`:(e.status==='orcamento'?'Aguardando aceite':'Disponível'),e.status==='orcamento'?'locked':''],
    ['financeiro','💵','Financeiro',e.entradaPaga?'Entrada confirmada':'Registrar entrada',(!e.contratoAssinado&&!['contrato','entrada','preparacao','pronto','realizado'].includes(e.status))?'locked':''],
    ['resumo','🎉','Detalhes da festa',detailsUnlocked(e)?'Abrir informações':'Bloqueado',detailsUnlocked(e)?'':'locked'],
    ['checklist','✅','Checklist',detailsUnlocked(e)?`${pending} pendência(s)`:'Bloqueado',detailsUnlocked(e)?'':'locked'],
    ['consumo','📦','Consumo',detailsUnlocked(e)?'Abrir consumo':'Bloqueado',detailsUnlocked(e)?'':'locked'],
    ['arquivos','📁','Arquivos',detailsUnlocked(e)?'Documentos e imagens':'Bloqueado',detailsUnlocked(e)?'':'locked'],
    ['painel','📊','Painel do evento','Visão geral sob consulta',''],
    ['historico','📜','Histórico','Movimentações e versões','']
  ];
  return `${eventAnalysis(e)}<section class="event-menu-grid">${items.map(([id,icon,title,subtitle,locked])=>`<button class="event-menu-card ${locked}" data-action="tab" data-tab="${id}" ${locked?'disabled':''}><span class="event-menu-card__icon">${icon}</span><span><strong>${title}</strong><small>${subtitle}</small></span></button>`).join('')}</section>`;
}
function eventPanel(e){const q=selectedQuote(e)||{};const total=(e.checklist||[]).length;const done=(e.checklist||[]).filter(i=>i.concluido).length;return `<section class="panel"><div class="panel-header"><div><h2>Painel do evento</h2><p>Resumo disponível somente quando você precisar consultar.</p></div></div><dl class="budget-data"><div><dt>Data</dt><dd>${dateBR(q.data)}</dd></div><div><dt>Pacote</dt><dd>${esc(q.pacote||'')}</dd></div><div><dt>Convidados</dt><dd>${q.convidadosTotal||0}</dd></div><div><dt>Valor contratado</dt><dd>${money(q.valor||0)}</dd></div><div><dt>Contrato</dt><dd>${e.contratoAssinado?'Assinado':(e.contratos?.length?'Gerado':'Pendente')}</dd></div><div><dt>Entrada</dt><dd>${e.entradaPaga?'Confirmada':'Pendente'}</dd></div><div><dt>Checklist</dt><dd>${done} de ${total}</dd></div><div><dt>Status</dt><dd>${statusMeta(e.status)[1]}</dd></div></dl></section>`;}
function workspace(e){const q=selectedQuote(e)||{};const[,label,icon]=statusMeta(e.status);let content=eventMenu(e);if(state.activeTab==='orcamento')content=budgetContent(e);if(state.activeTab==='contrato')content=contractContent(e);if(state.activeTab==='financeiro')content=financeContent(e);if(state.activeTab==='resumo')content=detailsUnlocked(e)?detailsContent(e):placeholder('Detalhes ainda bloqueados','Confirme o contrato e registre o pagamento da entrada para começar a completar a festa.');if(state.activeTab==='checklist')content=detailsUnlocked(e)?checklistContent(e):placeholder('Checklist ainda não iniciado','O checklist será liberado depois do contrato assinado e da entrada paga.');if(state.activeTab==='historico')content=historyContent(e);if(state.activeTab==='painel')content=eventPanel(e);if(state.activeTab==='consumo')content=detailsUnlocked(e)?placeholder('Consumo do evento','O consumo real será registrado nesta área.'):placeholder('Consumo ainda bloqueado','Disponível depois da entrada paga.');if(state.activeTab==='arquivos')content=detailsUnlocked(e)?placeholder('Arquivos','Documentos, imagens e anexos ficarão organizados aqui.'):placeholder('Arquivos da organização ainda bloqueados','Disponíveis depois da entrada paga.');return`<div class="page-grid"><section class="events-header workspace-header"><div><button class="back-link" data-action="back-list">← Voltar</button><span class="eyebrow">${icon} ${label}</span><h2>${esc(q.nome||q.cliente||'Evento')}</h2><p>${dateBR(q.data)}${q.horaInicio?` · ${q.horaInicio}`:''}</p></div><div class="workspace-header-actions">${state.activeTab!=='menu'?'<button class="btn btn-ghost" data-action="tab" data-tab="menu">☰ Menu do evento</button>':''}<button class="icon-button danger" data-action="delete-event">🗑</button></div></section>${content}</div>`;}

function currentTabFor(){return 'menu';}

function renderCurrent(){if(state.view==='new')return quoteForm();const e=getEvents().find(x=>x.id===state.selectedId);if(state.view==='version'&&e)return quoteForm(e);if(state.view==='workspace'&&e)return workspace(e);return listView();}

